(function(){'use strict';const API='/crm/api/email-templates.php';let templates={};let dirty={};document.addEventListener('DOMContentLoaded',function(){loadTemplates();hookSettingsForm()});function loadTemplates(){fetch(API).then(function(r){return r.json()}).then(function(data){if(!data.success){return}
data.templates.forEach(function(tpl){templates[tpl.template_key]=tpl;populateSection(tpl)})}).catch(function(){})}
function populateSection(tpl){var key=tpl.template_key;var subjectEl=document.getElementById('et_subject_'+key);var bodyEl=document.getElementById('et_body_'+key);if(subjectEl){subjectEl.value=tpl.subject||''}
if(bodyEl){bodyEl.value=tpl.body_text||''}}
function hookSettingsForm(){var form=document.getElementById('settingsForm');if(!form){return}
form.addEventListener('submit',function(){saveAllDirtyTemplates()})}
function saveAllDirtyTemplates(){var keys=Object.keys(dirty);if(keys.length===0){return}
keys.forEach(function(key){var subjectEl=document.getElementById('et_subject_'+key);var bodyEl=document.getElementById('et_body_'+key);if(!subjectEl||!bodyEl){return}
saveTemplate(key,subjectEl.value,bodyEl.value,!1)})}
function saveTemplate(key,subject,bodyText,showFeedback){return fetch(API,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':window.MW_CSRF_TOKEN||''},body:JSON.stringify({key:key,subject:subject,body_text:bodyText}),}).then(function(r){return r.json()}).then(function(data){if(data.success){templates[key]=data.template;delete dirty[key];if(showFeedback){showToast('Template saved','success')}}else{if(showFeedback){showToast('Save failed: '+(data.error||'unknown error'),'error')}}}).catch(function(){if(showFeedback){showToast('Network error saving template','error')}})}
window.etMarkDirty=function(key){dirty[key]=!0};window.etPreview=function(key){var overlay=document.getElementById('et-preview-overlay');var frame=document.getElementById('et-preview-frame');var loading=document.getElementById('et-preview-loading');if(!overlay||!frame){return}
overlay.style.display='flex';frame.style.display='none';if(loading){loading.style.display='block'}
var subjectEl=document.getElementById('et_subject_'+key);var bodyEl=document.getElementById('et_body_'+key);var savePromise;if(subjectEl&&bodyEl){savePromise=saveTemplate(key,subjectEl.value,bodyEl.value,!1)}else{savePromise=Promise.resolve()}
savePromise.then(function(){frame.src=API+'?preview='+encodeURIComponent(key)+'&t='+Date.now();frame.onload=function(){frame.style.display='block';if(loading){loading.style.display='none'}}})};window.etClosePreview=function(){var overlay=document.getElementById('et-preview-overlay');var frame=document.getElementById('et-preview-frame');if(overlay){overlay.style.display='none'}
if(frame){frame.src='about:blank'}};window.etResetDefault=function(key){if(!confirm('Reset "'+key.replace(/_/g,' ')+'" to the default text? Your edits will be lost.')){return}
fetch(API+'?defaults='+encodeURIComponent(key)).then(function(r){return r.json()}).then(function(data){if(data.success&&data.template){var tpl=data.template;var subjectEl=document.getElementById('et_subject_'+key);var bodyEl=document.getElementById('et_body_'+key);if(subjectEl){subjectEl.value=tpl.subject||''}
if(bodyEl){bodyEl.value=tpl.body_text||''}
saveTemplate(key,tpl.subject||'',tpl.body_text||'',!0)}}).catch(function(){showToast('Could not load defaults','error')})};window.etInsertPlaceholder=function(targetId,placeholder){var el=document.getElementById(targetId);if(!el){return}
var start=el.selectionStart;var end=el.selectionEnd;var text=el.value;el.value=text.substring(0,start)+placeholder+text.substring(end);el.selectionStart=el.selectionEnd=start+placeholder.length;el.focus();var key=targetId.replace('et_subject_','').replace('et_body_','');dirty[key]=!0};function showToast(msg,type){var toast=document.getElementById('toast')||document.getElementById('settingsSuccess')||document.getElementById('settingsError');if(!toast){return}
if(type==='success'&&document.getElementById('settingsSuccess')){var el=document.getElementById('settingsSuccess');el.textContent=msg;el.style.display='block';setTimeout(function(){el.style.display='none'},3000)}else if(type==='error'&&document.getElementById('settingsError')){var el2=document.getElementById('settingsError');el2.textContent=msg;el2.style.display='block';setTimeout(function(){el2.style.display='none'},4000)}}
document.addEventListener('click',function(e){var overlay=document.getElementById('et-preview-overlay');if(overlay&&e.target===overlay){window.etClosePreview()}});document.addEventListener('keydown',function(e){if(e.key==='Escape'){window.etClosePreview()}})}())